style.css:
@-moz-document domain("google.com") {
/* Transparent Teal & Pink Tint Layer Over Your Custom Image */
    body, #viewport, .L3eUgb {
        background: 
            linear-gradient(135deg, rgba(0, 128, 128, 0.55), rgba(255, 105, 180, 0.55)), 
            url("https://i.pinimg.com/736x/ce/09/89/ce0989067fdf1dc1aa2451c89fec1f16.jpg") !important;
        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;
        height: 100vh !important;
    }

    /* Clear Out White Boxes blocking the view */
    #gb, .notranslate, .Hp63Mc {
        background: transparent !important;
    }

    /* Make the Search Bar Glass-Like */
    .RNNXgb {
        background: rgba(255, 255, 255, 0.2) !important;
        border: 1px solid rgba(255, 255, 255, 0.4) !important;
        backdrop-filter: blur(8px) !important;
        box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2) !important;
    }

    /* Search Bar Text Color */
    .gLFyf {
        color: #ffffff !important;
        font-weight: 500 !important;
    }

    /* Voice & Lens Icons Glow */
    .XbVzOb, .Gdd5U {
        filter: drop-shadow(0px 0px 3px #ffffff) !important;
    }

    /* Custom Buttons */
    .FPdoLc input[type="submit"], .gNO89b {
        background: rgba(0, 128, 128, 0.7) !important;
        color: #ffffff !important;
        border: 1px solid #ff69b4 !important;
        border-radius: 4px !important;
    }

    /* Button Hover Effect */
    .FPdoLc input[type="submit"]:hover, .gNO89b:hover {
        background: #ff69b4 !important;
        border-color: #008080 !important;
    }

    /* Top Navigation and Footer Links */
    a, .gb_E {
        color: #ffffff !important;
        text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.4) !important;
    }
}
